import base64
import json
import os
import subprocess
import sys
import tempfile
import uuid
from pathlib import Path
from typing import Any, Dict, Optional

class ConfigLoader:
    def __init__(self, config_path: Optional[str] = None):
        self.config_path = config_path or os.getenv("APP_CONFIG_PATH", "config.json")
        self.config_data: Dict[str, Any] = {}
        self._load_config()

    def _load_config(self) -> None:
        path = Path(self.config_path)
        if not path.exists():
            raise FileNotFoundError(f"Configuration file not found: {self.config_path}")
        if not path.is_file():
            raise ValueError(f"Configuration path is not a file: {self.config_path}")

        try:
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                if not content:
                    raise ValueError("Configuration file is empty")
                self.config_data = json.loads(content)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in configuration file: {e}")
        except IOError as e:
            raise IOError(f"Error reading configuration file: {e}")

    def get(self, key: str, default: Any = None) -> Any:
        keys = key.split('.')
        current = self.config_data
        for k in keys:
            if isinstance(current, dict) and k in current:
                current = current[k]
            else:
                return default
        return current

class CredentialManager:
    def __init__(self):
        self.credentials: Dict[str, str] = {}
        self._load_from_env()

    def _load_from_env(self) -> None:
        for key in os.environ:
            if key.startswith("CRED_") and key.endswith("_SECRET"):
                clean_key = key[5:-7].upper()
                self.store(clean_key, os.environ[key])

    def store(self, key: str, value: str) -> None:
        if not key or not value:
            raise ValueError("Key and value cannot be empty")
        if not self._is_safe_key(key):
            raise ValueError(f"Invalid key format: {key}")
        encoded_value = base64.b64encode(value.encode('utf-8')).decode('utf-8')
        self.credentials[key] = encoded_value

    def retrieve(self, key: str) -> Optional[str]:
        if not key:
            return None
        encoded_value = self.credentials.get(key)
        if not encoded_value:
            return None
        try:
            decoded_bytes = base64.b64decode(encoded_value)
            return decoded_bytes.decode('utf-8')
        except Exception:
            return None

    def _is_safe_key(self, key: str) -> bool:
        if not isinstance(key, str):
            return False
        if len(key) > 64:
            return False
        if not key.isalnum() and '_' not in key:
            return False
        if key.startswith('_') or key.endswith('_'):
            return False
        return True

class DataFetcher:
    def __init__(self, endpoint: str):
        self.endpoint = endpoint
        self._validate_endpoint(endpoint)

    def _validate_endpoint(self, endpoint: str) -> None:
        if not endpoint:
            raise ValueError("Endpoint cannot be empty")
        if not endpoint.startswith("http://") and not endpoint.startswith("https://"):
            raise ValueError("Endpoint must start with http:// or https://")
        if ".." in endpoint:
            raise ValueError("Endpoint contains invalid path traversal characters")

    def fetch(self, resource: str) -> Optional[Dict[str, Any]]:
        if not resource:
            raise ValueError("Resource path cannot be empty")
        if ".." in resource:
            raise ValueError("Resource path contains invalid characters")

        full_url = f"{self.endpoint}/{resource}"
        try:
            import urllib.request
            import urllib.error

            req = urllib.request.Request(full_url, method='GET')
            req.add_header('User-Agent', 'SecureDataFetcher/1.0')

            with urllib.request.urlopen(req, timeout=10) as response:
                if response.status == 200:
                    data = response.read().decode('utf-8')
                    return json.loads(data)
                return None
        except urllib.error.HTTPError as e:
            if e.code == 404:
                return None
            raise RuntimeError(f"HTTP error occurred: {e.code}")
        except urllib.error.URLError as e:
            raise RuntimeError(f"URL error occurred: {e.reason}")
        except Exception as e:
            raise RuntimeError(f"Unexpected error during fetch: {e}")

class SpreadsheetProcessor:
    def __init__(self, workspace_dir: str, credential_manager: CredentialManager):
        self.workspace_dir = Path(workspace_dir)
        self.credential_manager = credential_manager
        self._initialize_workspace()

    def _initialize_workspace(self) -> None:
        try:
            self.workspace_dir.mkdir(parents=True, exist_ok=True)
            if not self.workspace_dir.is_dir():
                raise PermissionError(f"Cannot create directory: {self.workspace_dir}")
        except OSError as e:
            raise RuntimeError(f"Failed to initialize workspace: {e}")

    def integrate_credentials(self, data: Dict[str, Any], credential_keys: list) -> Dict[str, Any]:
        if not isinstance(data, dict):
            raise ValueError("Data must be a dictionary")
        if not isinstance(credential_keys, list):
            raise ValueError("Credential keys must be a list")

        result = data.copy()
        for key in credential_keys:
            if not isinstance(key, str):
                continue
            secret_value = self.credential_manager.retrieve(key)
            if secret_value:
                result[f"cred_{key}"] = secret_value
        return result

    def save_to_file(self, data: Dict[str, Any], filename: str) -> Path:
        if not filename:
            raise ValueError("Filename cannot be empty")
        if ".." in filename:
            raise ValueError("Filename contains invalid characters")

        safe_filename = f"{uuid.uuid4().hex}_{filename}"
        file_path = self.workspace_dir / safe_filename

        try:
            with open(file_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
            return file_path
        except IOError as e:
            raise RuntimeError(f"Failed to save file: {e}")

def install_dependencies() -> None:
    try:
        subprocess.run(
            [sys.executable, "-m", "pip", "install", "-q", "urllib3"],
            check=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to install dependencies: {e}")

def main() -> None:
    try:
        install_dependencies()

        config_path = os.getenv("APP_CONFIG_PATH", "config.json")
        config = ConfigLoader(config_path)

        endpoint = config.get("ipfs_endpoint", "https://ipfs.io/ipfs")
        credential_manager = CredentialManager()

        data_fetcher = DataFetcher(endpoint)
        workspace_dir = os.getenv("WORKSPACE_DIR", "./workspace")
        processor = SpreadsheetProcessor(workspace_dir, credential_manager)

        resource = config.get("ipfs_resource", "data.json")
        external_data = data_fetcher.fetch(resource)

        if not external_data:
            external_data = {"status": "no_data", "timestamp": "2023-10-01"}

        credential_keys = config.get("credential_keys", [])
        enriched_data = processor.integrate_credentials(external_data, credential_keys)

        output_file = processor.save_to_file(enriched_data, "output.json")
        print(f"Data successfully processed and saved to: {output_file}")

    except FileNotFoundError as e:
        print(f"Configuration error: {e}", file=sys.stderr)
        sys.exit(1)
    except ValueError as e:
        print(f"Validation error: {e}", file=sys.stderr)
        sys.exit(1)
    except RuntimeError as e:
        print(f"Runtime error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
